preConditionHook:
// MultiWalk's WFSafe_AvgTrueRange is a ROLLING accumulator, not a fresh N-term
// sum: seeded with a full sum on the study's first calculated bar, thereafter
// carrying S += TrueRange - TrueRange[Length], re-seeding when the length
// changes. Same block as AtrProfitTarget, including the TWO separate
// accumulator statements -- EasyLanguage evaluates
// Summation[1] + Price - Price[Length] left to right, and folding it to
// S += in - out rounds differently.
if (atrLenState != (int)atrLength) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLength; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLenState = (int)atrLength;
} else {
    const int out = (int)atrLength;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atrValue = atrSum / (int)atrLength;
// The climax test is ClimaxBar's, evaluated at each bar of the window against
// the CURRENT ATR -- one ATR read, not one per counted bar, which is how
// LargeTrendBarCountInWindow's family reads it and keeps the rule off the ATR
// variable's own history. A climax counts only when it is SEPARATED from the
// run before it: at least one of the maxGapBars bars immediately older than it
// is not itself a climax of the same direction. Without that clause this rule
// would be a plain count-in-window, which is not what Brooks means by
// consecutive climaxes.
bullCount = 0.0;
bearCount = 0.0;
for (ii = 0; ii < (int)windowBars; ++ii) {
    isBull = el_gt(close[ii], open[ii])
        && el_ge(close[ii] - open[ii], bodyFraction * (high[ii] - low[ii]))
        && el_ge(high[ii] - low[ii], climaxMultiple * atrValue);
    isBear = el_lt(close[ii], open[ii])
        && el_ge(open[ii] - close[ii], bodyFraction * (high[ii] - low[ii]))
        && el_ge(high[ii] - low[ii], climaxMultiple * atrValue);
    sepBull = false;
    sepBear = false;
    for (jj = ii + 1; jj <= ii + (int)maxGapBars; ++jj) {
        gapBull = el_gt(close[jj], open[jj])
            && el_ge(close[jj] - open[jj], bodyFraction * (high[jj] - low[jj]))
            && el_ge(high[jj] - low[jj], climaxMultiple * atrValue);
        gapBear = el_lt(close[jj], open[jj])
            && el_ge(open[jj] - close[jj], bodyFraction * (high[jj] - low[jj]))
            && el_ge(high[jj] - low[jj], climaxMultiple * atrValue);
        if (!gapBull) sepBull = true;
        if (!gapBear) sepBear = true;
    }
    if (isBull && sepBull) bullCount += 1;
    if (isBear && sepBear) bearCount += 1;
}
